/**
 * Error Handler Middleware — Centralized error handling with proper status codes.
 * Generated by BackendForge
 */

const { env } = require('../config/env');

/**
 * Custom API Error class.
 */
class ApiError extends Error {
  constructor(statusCode, message, code = 'ERROR', details = null) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.details = details;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }

  static badRequest(message, code, details) { return new ApiError(400, message, code || 'BAD_REQUEST', details); }
  static unauthorized(message, code) { return new ApiError(401, message, code || 'UNAUTHORIZED'); }
  static forbidden(message, code) { return new ApiError(403, message, code || 'FORBIDDEN'); }
  static notFound(message, code) { return new ApiError(404, message, code || 'NOT_FOUND'); }
  static conflict(message, code) { return new ApiError(409, message, code || 'CONFLICT'); }
  static tooMany(message, code) { return new ApiError(429, message, code || 'TOO_MANY_REQUESTS'); }
  static internal(message, code) { return new ApiError(500, message, code || 'INTERNAL_ERROR'); }
}

/**
 * 404 Not Found handler.
 */
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    success: false,
    message: `Route not found: ${req.method} ${req.originalUrl}`,
    code: 'ROUTE_NOT_FOUND',
  });
};

/**
 * Global error handler.
 */
const errorHandler = (err, req, res, next) => {
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal server error';
  let code = err.code || 'INTERNAL_ERROR';
  let details = err.details || null;

  // Sequelize validation errors
  if (err.name === 'SequelizeValidationError') {
    statusCode = 400;
    code = 'VALIDATION_ERROR';
    message = 'Validation failed';
    details = err.errors?.map(e => ({ field: e.path, message: e.message }));
  }

  // Sequelize unique constraint
  if (err.name === 'SequelizeUniqueConstraintError') {
    statusCode = 409;
    code = 'DUPLICATE_ENTRY';
    message = 'A record with this value already exists';
    details = err.errors?.map(e => ({ field: e.path, value: e.value }));
  }

  // Mongoose validation errors
  if (err.name === 'ValidationError' && err.errors) {
    statusCode = 400;
    code = 'VALIDATION_ERROR';
    message = 'Validation failed';
    details = Object.values(err.errors).map(e => ({ field: e.path, message: e.message }));
  }

  // Mongoose duplicate key
  if (err.code === 11000) {
    statusCode = 409;
    code = 'DUPLICATE_ENTRY';
    const field = Object.keys(err.keyPattern || {})[0];
    message = `Duplicate value for: ${field}`;
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    statusCode = 401;
    code = 'INVALID_TOKEN';
    message = 'Invalid authentication token';
  }

  if (err.name === 'TokenExpiredError') {
    statusCode = 401;
    code = 'TOKEN_EXPIRED';
    message = 'Authentication token has expired';
  }

  // Log error in development
  if (env.NODE_ENV === 'development') {
    console.error(`\n❌ [${req.requestId || '-'}] ${err.stack || err}\n`);
  }

  // Response
  const response = {
    success: false,
    message,
    code,
    ...(details && { details }),
    ...(env.NODE_ENV === 'development' && { stack: err.stack }),
    requestId: req.requestId,
  };

  res.status(statusCode).json(response);
};

module.exports = { ApiError, errorHandler, notFoundHandler };
